function CounterCard({person}) {
  const [count, setCount] = React.useState(0);
  return <li data-person={person.id}>
    <span>{person.name}: {count}</span>
    <button aria-label={"Add for " + person.name} onClick={() => setCount(c => c + 1)}>Add</button>
  </li>;
}
function App() {
  const [people, setPeople] = React.useState([{id:"a",name:"Ari"},{id:"b",name:"Bea"}]);
  return <main>
    <button onClick={() => setPeople(current => [...current].reverse())}>Reverse order</button>
    <ul>{people.map((person, index) => <CounterCard key={person.id} person={person} />)}</ul>
  </main>;
}

const LanguageContext = React.createContext("English");
function Greeting() {
  const language = React.useContext(LanguageContext);
  return <p>{language}</p>;
}
function App() {
  return <main><Greeting /><LanguageContext.Provider value="Spanish"><Greeting /></LanguageContext.Provider></main>;
}

function useToggle(initial) {
  const [enabled, setEnabled] = React.useState(initial);
  return [enabled, () => setEnabled(value => !value)];
}
function App() {
  const [enabled, toggle] = useToggle(true);
  return <button onClick={toggle}>{enabled ? "On" : "Off"}</button>;
}

class SmallBoundary extends React.Component {
  constructor(props) { super(props); this.state = {failed:false}; }
  static getDerivedStateFromError() { return {failed:true}; }
  render() { return this.state.failed ? <p>Try again later</p> : this.props.children; }
}
function BrokenPanel() { throw new Error("Demo failure"); }
function App() {
  return <SmallBoundary><BrokenPanel /></SmallBoundary>;
}

let finishGreeting;
const greetingModule = new Promise(resolve => {
  finishGreeting = () => resolve({default: Greeting});
});
function Greeting() { return <p data-greeting>Hello, explorer</p>; }
const LazyGreeting = React.lazy(() => greetingModule);
function App() {
  return <main><button onClick={() => finishGreeting()}>Finish local load</button>
    <React.Suspense fallback={<p role="status">Preparing greeting</p>}>
      <LazyGreeting />
    </React.Suspense>
  </main>;
}

